node --input-type=module - <<'EOF'
import fs from "node:fs";
const load = (code) => import("data:text/javascript," + encodeURIComponent(code));
const { carve } = await load(fs.readFileSync("carve.js", "utf8"));
const src = fs.readFileSync("game.package.js", "utf8");
const body = src.slice(src.indexOf("const IDLE"), src.indexOf("export const gameRuntime"));
const neu = (await load(body)).gameStep;
const old = (await load(body.replace("down ? s.depth + 1", "onExit ? s.depth + 1"))).gameStep;
// stand-in for the kit: 30 Hz ticks, host reads depth every 3 ticks, the new cave lands before the next tick
function sim(step, pad, n = 45) {
  let s = { t: 0, depth: 0, miner: { x: -1, y: -1 }, start: [-1, -1], taken: false };
  let built = 0, next = null, lv = carve(7, 0, 45);
  const builds = [];
  for (let k = 1; k <= n; k++) {
    if (next !== null) { built = next; lv = carve(7, built, 45); next = null; builds.push([k, built]); }
    s = step(s, { dt: 1 / 30, inputs: { start: [lv.start.x, lv.start.y], exit: [lv.exit.x, lv.exit.y] }, controls: { pad: pad(k) },
      kernels: { control: (m, p) => { m.dx = p.right ? 1 : p.left ? -1 : 0; m.dy = 0; } } });
    if (k % 3 === 0 && s.depth !== built) next = s.depth;
  }
  return `depth ${s.depth} miner ${s.miner.x},${s.miner.y} builds(tick,depth) ${JSON.stringify(builds)}`;
}
const hold = (a, b) => (k) => ({ right: k >= a && k <= b });
for (const [label, pad] of [["log: right on ticks 1-7", hold(1, 7)], ["arrive tick 8", hold(2, 8)], ["arrive tick 9", hold(3, 9)],
  ["held past exit", hold(1, 9)], ["step off and back", (k) => ({ right: k <= 7 || k === 9, left: k === 8 })]]) {
  console.log(`${label}\n  old: ${sim(old, pad)}\n  new: ${sim(neu, pad)}`);
}
for (const d of [0, 1, 2, 3]) { const l = carve(7, d, 45); console.log("depth", d, "start", l.start.x, "exit", l.exit.x); }
console.log("grid same at roughness 45/46:", JSON.stringify(carve(7, 3, 45)) === JSON.stringify(carve(7, 3, 46)));
EOF
